mod tui_runtime_regressions;

#[cfg(all(test, feature = "debug-server"))]
mod gift_dialogue_debug_tests {
    use super::*;
    #[test]
    fn control_ready_waits_for_boulder_slide_dust_and_graphics_restore() {
        use pokered_core::overworld::{Direction,OverworldScreen};
        use pokered_data::impl_traits::PokemonRedData;
        let mut game=PokemonGame::new_with_options(
            GameVersion::Red,None,None,None,false,None,false,true,None,
        );
        game.state.screen=GameScreen::Overworld;
        game.overworld=OverworldScreen::new(MapId::SeafoamIslands1F,None,PokemonRedData);
        game.overworld.run_on_load();
        let idle=InputState::new();
        for _ in 0..120 {game.update(&idle);}
        game.overworld.state.player.x=18;game.overworld.state.player.y=9;
        game.overworld.state.player.facing=Direction::Down;
        game.overworld.strength_active=true;
        // The initial direction sample can roll a cave encounter before the
        // boulder push starts. This test owns the push presentation only.
        game.overworld.state.encounter_cooldown=1;
        let mut down=InputState::new();down.press(GbButton::Down);
        for _ in 0..10 {
            game.update(&down);
            if game.overworld.boulder_push.is_some() {break;}
        }
        assert!(game.overworld.boulder_push.is_some());
        let mut elapsed=0;
        while game.overworld.boulder_push.is_some() {
            let completed=game.overworld.boulder_push.unwrap().frame>=
                pokered_core::overworld::presentation::BoulderPushState::COMPLETION_FRAME;
            assert_eq!(game.debug_condition_met("control_ready"),completed,
                "logical control resumes before the last LCD image");
            game.update(&idle);elapsed+=1;assert!(elapsed<=72);
        }
        assert!(elapsed>=71);
        assert!(game.debug_condition_met("control_ready"));
    }

// RunMapScript precedes JoypadOverworld: boulders consume the
// preceding field input, before player collision or movement.
if ordinary_field_loop && self.boulder_push.is_none()
    && self.state.player.movement_state == MovementState::Idle
    && self.state.walk_counter == 0 {
    let old=self.sampled_player_input.as_input();
    let direction = if old.down { Some(Direction::Down) }
        else if old.up { Some(Direction::Up) }
        else if old.left { Some(Direction::Left) }
        else if old.right { Some(Direction::Right) }
        else { None };
    self.tick_boulder_push(direction);
    if self.boulder_push.is_some() { return ScreenAction::Continue; }
}

// JoypadOverworld is not sampled while a step is in progress.
// A short START pulse during the step is discarded; a held START
// becomes a fresh press at the next idle sample. START precedes A.
let (control_start_just_pressed, control_a_just_pressed) = self.sample_idle_field_buttons(input);

if movement_before == MovementState::Idle && self.active_script_effect.is_none()
    && self.scripted_player_path.is_empty() && !self.cutscene_manager.is_blocking() {
    if let Some(direction) = movement_input.direction_pressed() {
        let direction_mask = match direction {
            Direction::Right => 1, Direction::Left => 2,
            Direction::Down => 4, Direction::Up => 8,
        };
        turning_in_place = self.check_player_turn
            && direction_mask != self.player_last_stop_direction;
        if turning_in_place { self.check_player_turn = false; }
        self.player_moving_direction = direction_mask;
        self.state.player.facing = direction;
    }
}
let result = if turning_in_place {

    }
}
MoveResult::TurnedOnly => {
    // holdIntermediateDirectionLoop → call NewBattle
    // (home/overworld.asm:224-234): a completed 180° turn-in-
    // place ROLLS the wild-encounter check (and burns a repel
    // step) exactly like a completed step. Record it; the
    // roll runs after the map borrow ends (same queue as the
    // on-step check below).
    self.bump_anim_counter = 0;
    if self.pending_wild_encounter.is_none() && turn_encounter_check.is_none() {
        turn_encounter_check = Some((
            map.id,
            map.tileset,
            standing_tile,
            wild_encounters::encounter_rate_tile(
                map.tileset, &map.blocks, map.width,
                self.state.player.x, self.state.player.y,
            ),
        ));
    }
}

let roll_gated =
    !standing_on_warp && !has_script_effect && self.state.encounter_cooldown == 0;
let mut wore_off = false;
if roll_gated {
    if self.state.repel_steps > 0 {
        self.state.repel_steps -= 1;
        if self.state.repel_steps == 0 {
            wore_off = true;
        }
    }
}
if wore_off {
    // .lastRepelStep: the "wore off" step never rolls an encounter.
    return true;
}

let encounter_roll = self.rng.gen_range(0u8..=255);
let slot_roll = self.rng.gen_range(0u8..=255);

let randoms = WildEncounterRandoms {
    encounter_roll,
    slot_roll,
};

let context = EncounterContext {
    repel_active: self.state.repel_steps > 0,
    // Gen-1 repel compares wild level against the LEAD (first) party
    // member's level. The OverworldScreen does not own the full party,
    // so the app layer keeps `party_lead_level` in sync from save data.
    party_lead_level: self.party_lead_level,
};

let result = wild_encounters::check_wild_encounter_with_tables(
    map_id,
    tileset,
    standing_tile,
    right_tile,
    &self.wild_data_state.grass,
    &self.wild_data_state.water,
    &randoms,
    &context,
    standing_on_warp,
    has_script_effect,
    self.state.encounter_cooldown,
);

if let crate::battle::wild::WildEncounterResult::Encounter { level, species } = result {
    self.pending_wild_encounter = Some(PendingWildEncounter { species, level, old_man: false, hooked: false });
